# shieldgamma: each rule of src/shieldgamma.cpp removed once; tests/shieldgamma_test.cpp must fail on every one
runm shieldgamma sg_mat_ignored     src/shieldgamma.cpp 's/At<std::uint64_t>(d, kDMat) != kMat || //'
